add_action( 'wp_footer', 'perfectpixel_auto_update_cart_on_quantity' );

function perfectpixel_auto_update_cart_on_quantity() {
	if ( ! function_exists( 'is_cart' ) || ! is_cart() ) {
		return;
	}
	?>
	<style>.woocommerce-cart-form button[name="update_cart"]{display:none!important}</style>
	<script>
	jQuery( function ( $ ) {
		var timer;
		$( document.body ).on( 'change input', '.woocommerce-cart-form input.qty', function () {
			clearTimeout( timer );
			timer = setTimeout( function () {
				$( 'button[name="update_cart"]' ).prop( 'disabled', false ).trigger( 'click' );
			}, 600 );
		} );
	} );
	</script>
	<?php
}
